const voiceFor=(run,target)=>Object.hasOwn(PERSONAS,target)?target==='alice'?(isCareerContentV71(run)?ALICE_VOICE_V71:null):VOICES[target]||(isCastV74(run)?castPatronageVoiceV74(target):null)||(isExpansionV65(run)?VOICES_V65[target]:null):null;
const clamp=(value,min,max)=>Math.max(min,Math.min(max,value));
function contextOf(event){
 const id=String(event?.id||'');
 if(event?.scope==='private'||event?.privateContext===true||id.startsWith('meal-with-')||['kind-break','kind-workday','banquet-afterparty'].includes(id))return 'private';
 const text=[id,event?.title,event?.body,event?.wing].join(' ');
 if(/pip|PIP|改善計畫|改善期/.test(text))return 'pip';
 if(/dismissal|crisis-boss|paperwork|離場文件|自願離職書|資遣通知/.test(text))return 'dismissal';
 if(/salary-cut|low-pay|低薪|降薪|砍薪/.test(text))return 'salary';
 if(/career|promotion|升遷|升職|職涯/.test(text))return 'career';
 return 'work';
}
const CONTEXT_LINES=Object.freeze({
 entitled:{work:'',private:'',pip:'改善標準先拿去問清楚。',dismissal:'先打通電話，確認名單真的有我。',salary:'我的薪資單先別動，去請示清楚。',career:'職稱、授權跟薪水先拿來給我看。'},
 flattery:{work:'',private:'',pip:'標準請您指點，我一定好好記。',dismissal:'您先別動氣，我想再聽您的意思。',salary:'待遇請您指點，自己人先顧大局。',career:'您看我該往哪裡走，我跟您的方向。'}
});
export function patronageReplyLineV43(run,event,target){
 const v=voiceFor(run,target);
 if(!v)return '';
 const context=contextOf(event),mode=patronageReplyModeV43(target);
 return `${context==='private'?v.privateLine:v.line}${CONTEXT_LINES[mode][context]}`;
}

