const WING_REPORTED=new Set(['rick','hope','erich','sonny','jenjen','meimei','helen','owen','cindy','princess','joyce']);
const REACTIONS=['obliged','retort','reported','welcomed'];
const LABELS={obliged:'勉強照辦',retort:'當面頂回來',reported:'轉找人確認',welcomed:'意外接得住'};
const PRIVATE_LABELS={obliged:'給面子但冷場',retort:'下班不吃這套',reported:'話題繞過你',welcomed:'架子收成玩笑'};
export function patronageReplyOutcomesV43(run,event,target,{affinity=50}={}){
 const v=voiceFor(run,target);
 if(!v)return [];
 const mode=patronageReplyModeV43(target),context=contextOf(event),social=context==='private',s=run?.stats||{};
 const mood=clamp(Number.isFinite(s.mood)?s.mood:50,0,100),relationship=clamp(Number.isFinite(affinity)?affinity:50,0,100);
 const weights=mode==='flattery'?[40,26,18,16]:[39,30,17,14];
 if(mode==='entitled'&&['professor','joyce','helen','owen','princess','hope','erich','jenjen'].includes(target)){weights[0]-=7;weights[1]+=4;weights[2]+=3;}
 if(mood<30){weights[1]+=7;weights[2]+=3;weights[3]-=4;}
 if(relationship>=70){weights[0]+=4;weights[2]-=4;weights[3]+=7;}
 if(relationship<35){weights[0]-=5;weights[1]+=5;weights[2]+=5;weights[3]-=4;}
 if(target==='wing'){
  const boss=clamp(Number.isFinite(s.boss)?s.boss:50,0,100);
  if(boss>=70){weights[0]+=6;weights[1]-=6;weights[3]+=8;}
  if(boss<30){weights[1]+=12;weights[2]+=6;weights[3]-=5;}
 }
 const outcomes=REACTIONS.map((reaction,index)=>{
  const privateReactions=target==='alice'&&isCareerContentV71(run)?ALICE_PRIVATE_V71:PRIVATE_REACTIONS[target]||(isCastV74(run)?castPrivatePatronageV74(target):null)||(isExpansionV65(run)?PRIVATE_REACTIONS_V65[target]:null);
  let result=social&&privateReactions?privateReactions[index]:v[reaction];
  if(social&&mode==='flattery')result=target==='wing'?[
   '翅膀聽得很受用，順手請你替大家張羅下一輪。你原本只想捧一句，最後連飯局的小事也接到手上；他覺得自己人就是懂事，你則發現拍完馬屁仍然得親自去拿杯子。',
   '翅膀問你，平常也這麼懂事，事情怎麼還有沒做好的地方。你本想把飯局哄熱，先收到一段臨時訓話；今晚沒有立刻變成人事案，只是你那口氣被迫陪他坐得更久。',
   '翅膀當桌誇你最懂他，接著把招呼大家的事都交過來。旁人看著你忙，他仍很滿意這位自己人；沒有誰被趕走，只有你原本打算坐下休息的時間先被拿去表現。',
   '翅膀笑著接了話，也願意讓大家把眼前這頓飯吃完。你沒有再替每句閒聊加一段願景，他難得也沒多開一場會；這份奉承算有落地，今晚至少多了一點真的休息。'
  ][index]:[
   '屎潘蛇笑著接過你的話，請你替大家再張羅一輪。你得到一點董事長的好臉色，也多跑幾趟桌邊；今晚沒有多一筆經費，只有你捧出去的面子得親自幫忙擺回桌上。',
   '屎潘蛇說自己人更懂節省，接著聊起這桌還能怎麼省。你原本想捧個氣氛，先聽完一堂聚餐成本課；他沒有因此動怒，其他人卻開始認真研究怎麼把話題帶回菜單。',
   '屎潘蛇請你待會也把這份心意講給翅膀聽。你還沒坐穩，又多一輪得自己完成的敬意；這回不是同事告狀，只是你那句漂亮話被董事長順手排了一場追加演出。',
   '屎潘蛇難得把願景放一會，跟你聊起眼前這桌的人。你也收回後面那段準備好的奉承，兩人反而多說幾句；今晚沒有誰敲鐘，至少這段聊天不用再等下一次上市日期。'
  ][index];
  const delta=mode==='flattery'?[
   {mood:3,energy:-5,trust:-3,lick:2},{mood:-9,energy:-4,trust:-2},{mood:-5,energy:-6,trust:-4,lick:1},{mood:9,energy:-2,trust:1,lick:2}
  ][index]:[
   {mood:5,energy:-4,trust:-5},{mood:-10,energy:-5,trust:-3},{mood:-7,energy:-6,trust:-4},{mood:10,energy:-2,trust:2}
  ][index];
  if(target==='wing')delta.boss=[5,-3,2,6][index];
  else if(!social&&reaction==='reported'&&WING_REPORTED.has(target))delta.boss=-2;
  // Spencer's own impression never becomes Wing's mood, and a private
  // complaint stays social even when that person could report at work.
  return {reaction,weight:Math.max(2,weights[index]),label:social?PRIVATE_LABELS[reaction]:mode==='flattery'?['順手再交一件','馬屁拍出新功課','當眾追加表現','難得被聽進去'][index]:LABELS[reaction],result,delta,affinityDelta:(mode==='flattery'?[5,-6,2,9]:[-7,-13,-10,7])[index]};
 });
 return withPatronageOutcomesV67(run,event,target,outcomes);
}
